import pandas as pd
import networkx as nx
import numpy as np

class GRNPerturbationEngine:
    def __init__(self, edges_csv_path):
        """Load the edge list CSV generated by Student A and initialize the graph."""
        self.edges_df = pd.read_csv(edges_csv_path)
        self.base_graph = nx.Graph()
        
        for _, row in self.edges_df.iterrows():
            self.base_graph.add_edge(row['gene_1'], row['gene_2'], weight=row['weight'])
            
        print(f"Loaded base graph with {self.base_graph.number_of_nodes()} nodes and {self.base_graph.number_of_edges()} edges.")

    def simulate_knockout(self, target_genes):
        """
        Simulate target gene knockout by removing nodes and calculating impact metrics.
        
        Parameters:
            target_genes (list): List of gene symbols to knock out (e.g., ['TP53', 'ESR1'])
            
        Returns:
            dict: Summary of structural changes and network impact metrics.
        """
        if isinstance(target_genes, str):
            target_genes = [target_genes]
            
        # Create a copy of the base graph to perturb
        perturbed_graph = self.base_graph.copy()
        
        # Verify target presence
        valid_targets = [g for g in target_genes if g in perturbed_graph]
        if not valid_targets:
            raise ValueError(f"None of the targets {target_genes} exist in the current network.")

        # Baseline metrics before knockout
        orig_nodes = self.base_graph.number_of_nodes()
        orig_edges = self.base_graph.number_of_edges()
        orig_components = nx.number_connected_components(self.base_graph)
        orig_largest_cc = len(max(nx.connected_components(self.base_graph), key=len)) if orig_nodes > 0 else 0

        # Execute knockout (node removal)
        perturbed_graph.remove_nodes_from(valid_targets)
        
        # Post-knockout metrics
        new_nodes = perturbed_graph.number_of_nodes()
        new_edges = perturbed_graph.number_of_edges()
        new_components = nx.number_connected_components(perturbed_graph)
        new_largest_cc = len(max(nx.connected_components(perturbed_graph), key=len)) if new_nodes > 0 else 0

        # Calculate network disruption score
        edge_loss_pct = ((orig_edges - new_edges) / orig_edges) * 100 if orig_edges > 0 else 0
        cc_fragmentation_delta = new_components - orig_components
        largest_cc_reduction_pct = ((orig_largest_cc - new_largest_cc) / orig_largest_cc) * 100 if orig_largest_cc > 0 else 0

        results = {
            "knocked_out_genes": valid_targets,
            "original_nodes": orig_nodes,
            "remaining_nodes": new_nodes,
            "original_edges": orig_edges,
            "remaining_edges": new_edges,
            "edges_removed": orig_edges - new_edges,
            "edge_loss_percentage": round(edge_loss_pct, 2),
            "original_connected_components": orig_components,
            "new_connected_components": new_components,
            "network_fragmentation_delta": cc_fragmentation_delta,
            "largest_component_reduction_pct": round(largest_cc_reduction_pct, 2)
        }
        
        return results, perturbed_graph

# ==============================================================================
# TEST RUN FOR STUDENT B DELIVERABLE
# ==============================================================================
if __name__ == "__main__":
    engine = GRNPerturbationEngine("network_edges.csv")
    
    # Get all available nodes/genes in the constructed graph
    available_genes = list(engine.base_graph.nodes())
    
    if not available_genes:
        print("Error: The graph has no nodes/edges. Check network_edges.csv!")
    else:
        # Check if ESR1 is in the graph; if not, fall back to the highest degree gene
        target = 'ESR1' if 'ESR1' in available_genes else available_genes[0]
        
        print(f"\n--- Simulating Knockout of '{target}' ---")
        metrics, perturbed_g = engine.simulate_knockout([target])
        for k, v in metrics.items():
            print(f"  {k}: {v}")

        # Export a perturbed edge list for Student C testing
        perturbed_edges = nx.to_pandas_edgelist(perturbed_g)
        perturbed_edges.to_csv("perturbed_edges.csv", index=False)
        print(f"\nPerturbation test complete for '{target}'. Saved 'perturbed_edges.csv'.")